            aOrbiterF = (((aWandererF + RotL64(aIngress, 3U)) + RotL64(aCarry, 19U)) + 0x9386AAC712B34FDCULL) + aPhaseBOrbiterAssignSaltA[((aIndex + 27U)) & S_SALT1];
            aOrbiterH = ((aWandererJ + RotL64(aScatter, 12U)) + RotL64(aCarry, 57U)) + 0x62D330783D97A217ULL;
